use super::*;
fn fixture(code:i32)->(tempfile::TempDir,StorageRepository,ScheduleInput){let dir=tempfile::tempdir().unwrap();let repo=StorageRepository::at(dir.path().join("data")).unwrap();let input=crate::scheduler::tests::input(dir.path());let script=format!("const fs=require('node:fs');if(process.argv.includes('--version')){{console.log('fixture 1');process.exit(0)}}const data=[];process.stdin.on('data',c=>data.push(c));process.stdin.on('end',()=>{{fs.writeFileSync('received.txt',Buffer.concat(data));process.exit({code})}});");std::fs::write(dir.path().join("fixture.cjs"),script).unwrap();std::fs::write(&input.cli_path,if cfg!(windows){"@echo off\r\nnode \"%~dp0fixture.cjs\" %*\r\n"}else{"#!/bin/sh\nexec node \"$(dirname \"$0\")/fixture.cjs\" \"$@\"\n"}).unwrap();(dir,repo,input)}
#[test]fn noninteractive_stdin_preserves_unicode_quotes_newlines(){let(d,_,input)=fixture(0);assert_eq!(execute(&input).unwrap(),Some(0));assert_eq!(std::fs::read_to_string(d.path().join("received.txt")).unwrap(),input.prompt);assert!(!d.path().join("bad").exists());}
#[test]fn nonzero_exit_is_recorded_without_retry(){let(d,repo,input)=fixture(7);let s=Schedule{id:uuid::Uuid::new_v4().to_string(),input,status:ScheduleStatus::Pending};let id=uuid::Uuid::new_v4().to_string();ExecutionService::prepare(&repo,&s,&id).unwrap();run_job_at(&repo,&id).unwrap();let result=ExecutionService::result(&repo,&id).unwrap().unwrap();assert_eq!(result.exit_code,Some(7));assert!(result.error.is_some());assert!(run_job_at(&repo,&id).is_err());assert!(d.path().join("received.txt").exists());}
#[test]fn denied_cli_exit_is_not_completed(){let(_dir,_repo,input)=fixture(13);assert_eq!(execute(&input).unwrap(),Some(13));}
#[test]fn unsigned_tampered_ticket_never_runs(){let(d,repo,input)=fixture(0);let s=Schedule{id:uuid::Uuid::new_v4().to_string(),input,status:ScheduleStatus::Pending};let id=uuid::Uuid::new_v4().to_string();ExecutionService::prepare(&repo,&s,&id).unwrap();let path=repo.run_path(&id,"ticket").unwrap();let mut data:serde_json::Value=serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();data["signature"]="00".into();atomic(&path,&data).unwrap();assert!(run_job_at(&repo,&id).is_err());assert!(!d.path().join("received.txt").exists());}
